// src/js/firebaseConfig.js
import { initializeApp } from "firebase/app";
import { getAuth, GoogleAuthProvider, signInWithPopup, signOut } from "firebase/auth";
import { getFirestore } from "firebase/firestore";

const firebaseConfig = {
  apiKey: "AIzaSyAKFWffZymHk5ZAceWqQ-NI_ieV__fvUSU", 
  authDomain: "chattestedb.firebaseapp.com",
  projectId: "chattestedb",
  storageBucket: "chattestedb.firebasestorage.app",
  messagingSenderId: "374274715726",
  appId: "1:374274715726:web:1c70c9d4ba901e0fbd931f",
  measurementId: "G-VF9NGDT9FM"
};

const app = initializeApp(firebaseConfig);

export const auth = getAuth(app);
export const provider = new GoogleAuthProvider();
export const db = getFirestore(app);

export const loginWithGoogle = () => signInWithPopup(auth, provider);

export const logout = () => signOut(auth);
